// Auto-generated from the HelperChain hub diagrams, re-skinned to the Foundation palette.
// Both SVGs (circular engine + 14-venture living system) animate via scoped CSS under .sbdiag.
const DIAGRAM_STYLE = `.sbdiag{--green:#2c7a70;--green2:#4db6ac;--gold:#e6a23c;--display:'Inter',system-ui,sans-serif;}
.sbdiag .hcring{width:100%;max-width:360px;height:auto;display:block;margin:6px auto 0;}
.sbdiag .hcring .node circle{fill:#fff;stroke:var(--green2);stroke-width:2;filter:drop-shadow(0 2px 5px rgba(45,140,130,.18));}
.sbdiag .hcring .nemoji{font-size:26px;text-anchor:middle;dominant-baseline:central;}
.sbdiag .hcring .nlabel{font-size:12.5px;font-weight:800;fill:var(--green);text-anchor:middle;}
.sbdiag .hcring .rc1{font-size:15px;font-weight:700;fill:var(--green);font-family:var(--display);}
.sbdiag .hcring .rc2{font-size:11px;font-weight:700;fill:var(--gold);}
.sbdiag .hcring .flow{stroke-dasharray:16 12;animation:rflow 1.3s linear infinite;}
.sbdiag .hcring .spin{transform-box:view-box;transform-origin:210px 210px;animation:rspin 30s linear infinite;}
.sbdiag .hcring .orb{filter:drop-shadow(0 0 5px rgba(230,162,60,.9));}
@keyframes rflow{to{stroke-dashoffset:-28;}}
@keyframes rspin{to{transform:rotate(360deg);}}
.sbdiag .eng{display:block;width:min(860px,97vw);height:auto;margin:8px auto 4px;overflow:visible;}
.sbdiag .rail{stroke-linecap:round;animation:railflow 1.1s linear infinite;}
@keyframes railflow{to{stroke-dashoffset:-22;}}
.sbdiag .engcap-e{font-size:25px;text-anchor:middle;dominant-baseline:central;}
.sbdiag .engcap-l{font-size:13px;font-weight:800;text-anchor:middle;}
.sbdiag .engcap-l2{font-size:11.5px;font-weight:600;text-anchor:middle;}
.sbdiag .engcap{filter:drop-shadow(0 10px 22px rgba(45,140,130,.2));}
.sbdiag .engv-circ{fill:#fff;stroke:#cdc4ad;stroke-width:2;filter:drop-shadow(0 4px 10px rgba(45,140,130,.14));}
.sbdiag .engv-e{font-size:21px;text-anchor:middle;dominant-baseline:central;}
.sbdiag .engv-l{font-size:11px;font-weight:700;fill:#3d3d3d;dominant-baseline:central;}
.sbdiag .engpulse{transform-box:fill-box;transform-origin:center;animation:engp 2.9s ease-in-out infinite;}
@keyframes engp{0%,100%{transform:scale(1)}50%{transform:scale(1.05)}}
.sbdiag .susring{transform-box:fill-box;transform-origin:center;animation:susspin 120s linear infinite;}
@keyframes susspin{to{transform:rotate(360deg);}}
.sbdiag .susflow{stroke-dasharray:110 2076;animation:susf 9s linear infinite;}
@keyframes susf{to{stroke-dashoffset:-2186;}}
.sbdiag .susorb{filter:drop-shadow(0 0 6px rgba(230,162,60,.9));}
.sbdiag .suslabel{font-size:12.5px;font-weight:800;fill:#b9770e;text-anchor:middle;letter-spacing:.06em;text-transform:uppercase;}
.sbdiag .fr{display:block;width:min(900px,98vw);height:auto;margin:10px auto 4px;overflow:visible;}
.sbdiag .frlink{fill:none;stroke-linecap:round;animation:frflow 1.25s linear infinite;}
@keyframes frflow{to{stroke-dashoffset:-28;}}
.sbdiag .frin{filter:drop-shadow(0 6px 14px rgba(45,140,130,.18));}
.sbdiag .frv-c{fill:#fff;stroke:#cdc4ad;stroke-width:2;filter:drop-shadow(0 4px 10px rgba(45,140,130,.14));}
.sbdiag .fre{text-anchor:middle;dominant-baseline:central;}
.sbdiag .frin-l{font-size:12px;font-weight:800;text-anchor:end;dominant-baseline:central;}
.sbdiag .frv-l{font-size:12.5px;font-weight:800;fill:#3d3d3d;text-anchor:start;dominant-baseline:central;}
.sbdiag .frpulse{transform-box:fill-box;transform-origin:center;animation:frp 2.9s ease-in-out infinite;}
@keyframes frp{0%,100%{transform:scale(1)}50%{transform:scale(1.06)}}
.sbdiag .frhdr{font-size:12px;font-weight:800;letter-spacing:.05em;text-transform:uppercase;}
.sbdiag .opttl{font-size:11px;font-weight:800;fill:#3a9d90;text-anchor:middle;letter-spacing:.02em;}
.sbdiag .opst{font-size:10.5px;font-weight:700;fill:#3d3d3d;text-anchor:middle;}
.sbdiag .opsub{font-size:10.5px;font-weight:700;fill:#8a7a50;text-anchor:middle;font-style:italic;}
.sbdiag .brlbl{font-size:11px;font-weight:800;fill:#3a9d90;text-anchor:middle;letter-spacing:.03em;}
@media(prefers-reduced-motion:reduce){.sbdiag .flow,.sbdiag .spin,.sbdiag .rail,.sbdiag .susflow,.sbdiag .susring,.sbdiag .engpulse,.sbdiag .susorb,.sbdiag .orb,.sbdiag .frlink,.sbdiag .frpulse{animation:none!important;}}`

